import java.net.URI;
import java.util.List;
import java.util.Map;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;

import jakarta.servlet.http.HttpServletRequest;

@RestControllerAdvice
class FrameApiExceptionHandler {

    @ExceptionHandler(FrameNotFoundException.class)
    ResponseEntity<ProblemDetail> handleNotFound(
        FrameNotFoundException exception,
        HttpServletRequest request
    ) {
        return problem(HttpStatus.NOT_FOUND, "Frame not found", exception.getMessage(), request);
    }

    @ExceptionHandler(DuplicateFrameException.class)
    ResponseEntity<ProblemDetail> handleDuplicate(
        DuplicateFrameException exception,
        HttpServletRequest request
    ) {
        return problem(HttpStatus.CONFLICT, "Frame already exists", exception.getMessage(), request);
    }

    @ExceptionHandler(InvalidFrameRequestException.class)
    ResponseEntity<ProblemDetail> handleInvalidRequest(
        InvalidFrameRequestException exception,
        HttpServletRequest request
    ) {
        return problem(HttpStatus.BAD_REQUEST, "Invalid request", exception.getMessage(), request);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    ResponseEntity<ProblemDetail> handleValidation(
        MethodArgumentNotValidException exception,
        HttpServletRequest request
    ) {
        List<Map<String, String>> errors = exception.getBindingResult().getAllErrors().stream()
            .map(error -> Map.of(
                "field", error instanceof FieldError fieldError ? fieldError.getField() : error.getObjectName(),
                "message", error.getDefaultMessage() == null ? "is invalid" : error.getDefaultMessage()
            ))
            .toList();
        ResponseEntity<ProblemDetail> response = problem(
            HttpStatus.BAD_REQUEST,
            "Validation failed",
            "One or more fields are invalid",
            request
        );
        response.getBody().setProperty("errors", errors);
        return response;
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    ResponseEntity<ProblemDetail> handleUnreadable(
        HttpMessageNotReadableException exception,
        HttpServletRequest request
    ) {
        return problem(
            HttpStatus.BAD_REQUEST,
            "Invalid request body",
            "Request body is malformed or contains unsupported fields",
            request
        );
    }

    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
    ResponseEntity<ProblemDetail> handleTypeMismatch(
        MethodArgumentTypeMismatchException exception,
        HttpServletRequest request
    ) {
        return problem(
            HttpStatus.BAD_REQUEST,
            "Invalid request parameter",
            "Parameter '" + exception.getName() + "' has an invalid value",
            request
        );
    }

    private ResponseEntity<ProblemDetail> problem(
        HttpStatus status,
        String title,
        String detail,
        HttpServletRequest request
    ) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(status, detail);
        problem.setTitle(title);
        problem.setInstance(URI.create(request.getRequestURI()));
        return ResponseEntity.status(status).body(problem);
    }
}

package com.global.ct.frameinventory.frame;

import java.net.URI;
import java.util.Locale;
import java.util.Set;

import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.support.ServletUriComponentsBuilder;

import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/frames")
@CrossOrigin(origins = "*")
public class FrameController {

    private static final Set<String> SORT_FIELDS = Set.of(
        "frameId", "createdDate", "modifiedDate", "mediaType", "format", "environment", "status"
    );

    private final FrameService service;

    public FrameController(FrameService service) {
        this.service = service;
    }

    @PostMapping
    public ResponseEntity<FrameResponse> create(@Valid @RequestBody CreateFrameRequest request) {
        FrameResponse response = service.createFrame(request);
        URI location = ServletUriComponentsBuilder.fromCurrentRequest()
            .path("/{frameId}")
            .buildAndExpand(response.frameId())
            .encode()
            .toUri();
        return ResponseEntity.created(location).body(response);
    }

    @GetMapping("/{frameId}")
    public FrameResponse get(@PathVariable String frameId) {
        return service.getFrame(frameId);
    }

    @PutMapping("/{frameId}")
    public FrameResponse replace(
        @PathVariable String frameId,
        @Valid @RequestBody UpdateFrameRequest request
    ) {
        return service.replaceFrame(frameId, request);
    }

    @GetMapping
    public FramePageResponse search(
        @RequestParam(defaultValue = "0") int page,
        @RequestParam(defaultValue = "20") int size,
        @RequestParam(defaultValue = "modifiedDate,desc") String sort,
        @RequestParam(name = "q", required = false) String query,
        @RequestParam(required = false) String status,
        @RequestParam(required = false) String mediaType,
        @RequestParam(required = false) String environment,
        @RequestParam(required = false) String format,
        @RequestParam(required = false) String region
    ) {
        validatePage(page, size);
        PageRequest pageRequest = PageRequest.of(page, size, parseSort(sort));
        return service.searchFrames(
            new FrameSearchCriteria(query, status, mediaType, environment, format, region),
            pageRequest
        );
    }

    private void validatePage(int page, int size) {
        if (page < 0) {
            throw new InvalidFrameRequestException("page must be zero or greater");
        }
        if (size < 1 || size > 100) {
            throw new InvalidFrameRequestException("size must be between 1 and 100");
        }
    }

    private Sort parseSort(String value) {
        String[] parts = value.split(",", -1);
        if (parts.length != 2 || !SORT_FIELDS.contains(parts[0])) {
            throw new InvalidFrameRequestException("sort must use an allowed field and direction");
        }

        Sort.Direction direction;
        try {
            direction = Sort.Direction.valueOf(parts[1].toUpperCase(Locale.ROOT));
        } catch (IllegalArgumentException exception) {
            throw new InvalidFrameRequestException("sort direction must be asc or desc");
        }

        Sort primary = Sort.by(direction, parts[0]);
        return "frameId".equals(parts[0]) ? primary : primary.and(Sort.by("frameId"));
    }
}

