    @Valid SiteDto site,
    @Valid TechnicalDto technical,
    @Valid CommercialDto commercial,
    @Valid IntegrationDto integrations
) {
    public CreateFrameRequest {
        frameId = frameId == null ? null : frameId.trim();
    }
}
